UPDATE "criterion_assessment" SET "not_applicable_reason" = 'Begründung fehlt (Altbestand, nachzutragen)' WHERE "status" = 'not_applicable' AND ("not_applicable_reason" IS NULL OR char_length(btrim("not_applicable_reason")) < 10 OR char_length(btrim("not_applicable_reason")) > 500);--> statement-breakpoint
UPDATE "criterion_assessment" SET "not_applicable_reason" = NULL WHERE "status" <> 'not_applicable' AND "not_applicable_reason" IS NOT NULL;--> statement-breakpoint
ALTER TABLE "criterion_assessment" ADD CONSTRAINT "assessment_na_reason_check" CHECK (("criterion_assessment"."status" = 'not_applicable' AND "criterion_assessment"."not_applicable_reason" IS NOT NULL AND char_length(btrim("criterion_assessment"."not_applicable_reason")) BETWEEN 10 AND 500) OR ("criterion_assessment"."status" <> 'not_applicable' AND "criterion_assessment"."not_applicable_reason" IS NULL));